"""Executable regression examples, preserving every original Python block."""
BLOCKS = ('import torch\n'
 'from torch.utils.data import DataLoader, TensorDataset\n'
 'from hyso.training import Trainer\n'
 'from hyso.performance import measure_training_memory, TrainingMemoryProtocol\n'
 '\n'
 'model = torch.nn.Linear(3, 2)\n'
 'optimizer = torch.optim.AdamW(model.parameters(), lr=.01)\n'
 'trainer = Trainer(model, optimizer=optimizer, loss_fn=torch.nn.CrossEntropyLoss(),\n'
 '                  accum_steps=2)\n'
 'train = DataLoader(TensorDataset(torch.ones(5, 3), torch.tensor([0, 1, 0, 1, 0])),\n'
 '                   batch_size=2)\n'
 'result = measure_training_memory(trainer, train, epochs=1,\n'
 '    protocol=TrainingMemoryProtocol(device="cpu", max_samples=10000,\n'
 '                                    max_boundaries=10000, max_tensor_records=100000))\n'
 'data = result.to_dict()\n'
 'assert data["observations"][0]["logical"]["summary"]["optimizer"]["logical_bytes"] == 0\n'
 'assert data["observations"][-1]["logical"]["summary"]["optimizer"]["logical_bytes"] > 0\n'
 'assert data["activation"]["value"] is None\n',)
